import { servicesList } from "@/data/services";

export type ContentBlock =
  | { type: "paragraph"; text: string }
  | { type: "list"; items: string[] }
  | { type: "heading"; text: string };

export type ServiceFaq = { q: string; a: string };

export type ServiceData = {
  slug: string;
  title: string;
  eyebrow: string;
  intro: string;
  heroImage: string;
  overviewTitle: string;
  overview: ContentBlock[];
  includes: string[];
  recommendedFor: { title: string; text: string }[];
  faqTitle: string;
  faq: ServiceFaq[];
  ctaTitle: string;
  ctaText: string;
  relatedServices: string[];
};

const imageFor = (slug: string) =>
  servicesList.find((s) => s.slug === slug)?.image ?? "";

const defaultOverview: ContentBlock[] = [
  {
    type: "paragraph",
    text: "Съдържанието за тази страница предстои да бъде допълнено. Тук ще намерите подробно описание на процедурата, необходимата подготовка, продължителността и какво да очаквате по време на посещението.",
  },
  {
    type: "paragraph",
    text: "Екипът ни работи с индивидуален подход към всеки пациент и осигурява спокойна и сигурна среда, в която да получите ясни отговори на въпросите си.",
  },
];

const defaultCta = {
  ctaTitle: "Нуждаете се от повече информация?",
  ctaText:
    "Свържете се с нас или запазете час — екипът на клиниката ще Ви консултира и ще Ви насочи към най-подходящото решение за Вашия случай.",
};

const relatedFor = (slug: string) =>
  servicesList
    .filter((s) => s.slug !== slug)
    .slice(0, 3)
    .map((s) => s.slug);

function baseEntry(slug: string): ServiceData {
  const meta = servicesList.find((s) => s.slug === slug)!;
  return {
    slug,
    title: meta.title,
    eyebrow: "Медицински услуги",
    intro: meta.desc,
    heroImage: imageFor(slug),
    overviewTitle: "За услугата",
    overview: defaultOverview,
    includes: [],
    recommendedFor: [],
    faqTitle: "Често задавани въпроси",
    faq: [],
    ...defaultCta,
    relatedServices: relatedFor(slug),
  };
}

